// Normaliza o payload vindo do nó Hyperflow para o formato Meta Cloud API
// que o Synapse OS (Chatwoot) espera em /webhooks/hyperflow/:phone_number.
//
// Shape de saída (mesma envelope que Whatsapp::IncomingMessageBaseService parseia):
// {
//   object: 'whatsapp_business_account',
//   entry: [{ changes: [{ field: 'messages', value: { messaging_product, metadata, contacts, messages } }] }]
// }
//
// AJUSTE_AQUI: os nomes de campo do payload Hyperflow real podem diferir.
// Consulte Hyperflow > Painel > Webhook > 'Exemplo de evento' e troque as
// referências abaixo conforme necessário.

const results = [];
for (const item of $input.all()) {
  const h = item.json;

  // Identificação do número Synapse OS (precisa bater com Channel::Whatsapp#phone_number).
  // A Hyperflow pode entregar o número destino em h.to, h.phone ou h.business_phone.
  const phoneNumber = h.to || h.phone || h.business_phone || h.channel?.phone_number;

  // Contato remetente.
  const from = h.from || h.sender?.phone || h.contact?.phone;
  const name = h.sender?.name || h.contact?.name || h.profile?.name || '';

  // Tipo e corpo da mensagem.
  const type = h.type || h.message?.type || 'text';
  const text = h.text || h.message?.text?.body || h.message?.text || '';
  const mediaUrl = h.media?.url || h.message?.media?.url || h.attachment?.url;
  const mediaId = h.media?.id || h.message?.media?.id || h.attachment?.id;

  const messageObj = {
    from: from,
    id: h.message_id || h.id || String(Date.now()),
    timestamp: String(Math.floor(new Date(h.timestamp || Date.now()).getTime() / 1000)),
    type: type,
  };

  if (type === 'text') {
    messageObj.text = { body: text };
  } else if (['image', 'audio', 'video', 'document'].includes(type)) {
    messageObj[type] = {
      id: mediaId,
      url: mediaUrl,
      mime_type: h.media?.mime_type || h.message?.media?.mime_type,
      caption: h.message?.caption || h.caption || '',
    };
  } else {
    messageObj[type] = h.message || {};
  }

  results.push({
    json: {
      _phone_number: phoneNumber,
      body: {
        object: 'whatsapp_business_account',
        entry: [{
          id: h.account_id || h.business_id || 'unknown',
          changes: [{
            field: 'messages',
            value: {
              messaging_product: 'whatsapp',
              metadata: {
                display_phone_number: phoneNumber,
                phone_number_id: phoneNumber,
              },
              contacts: [{ wa_id: from, profile: { name: name } }],
              messages: [messageObj],
            },
          }],
        }],
      },
    },
  });
}
return results;
